svg.script:
(function(){
var W=320,H=180,HW=160,HH=90,FOC=277,cv=document.getElementById('c'),cx=cv.getContext('2d'),img=cx.createImageData(W,H),buf=new Uint32Array(img.data.buffer),SKY=0xFF140a06;
var CC=[[255,90,30],[255,200,60],[120,230,255],[235,250,255],[255,240,60],[170,200,255],[190,80,255],[255,80,200],[170,150,130],[110,220,130],[40,230,200],[240,240,255],[120,120,165],[255,210,40],[80,255,90],[255,40,40],[25,125,150],[160,180,255],[255,140,40],[60,255,140],[255,255,255],[255,200,60],[200,60,255],[220,40,50],[130,40,190],[150,255,60],[255,170,120]];
var pal=new Uint32Array(CC.length*16),i,j;
for(i=0;i<CC.length;i++)for(j=0;j<16;j++){var k=(j+1)/16;pal[i*16+j]=(0xFF000000|((CC[i][2]*k)|0)<<16|((CC[i][1]*k)|0)<<8|((CC[i][0]*k)|0))>>>0;}
var JT=new Float32Array(1536),TT=new Float32Array(512);
for(i=0;i<512;i++){var a,b,c;do{a=Math.random()*2-1;b=Math.random()*2-1;c=Math.random()*2-1;}while(a*a+b*b+c*c>1);JT[i*3]=a;JT[i*3+1]=b;JT[i*3+2]=c;TT[i]=(i*.6180339)%1;}
var STAR=new Float32Array(600);for(i=0;i<200;i++){var sa=Math.random()*6.283,sy=Math.random()*.9+.05,sr=Math.sqrt(1-sy*sy);STAR[i*3]=Math.cos(sa)*sr;STAR[i*3+1]=sy;STAR[i*3+2]=Math.sin(sa)*sr;}
var QF=[1,.75,.5,.33],GS=[1,2,2,3],Q=0,work=0,wc=0,fr=0,last=0,shk=0,PI=3.14159;
var ex=0,ey=0,ez=0,fx=0,fy=0,fz=1,RX=1,RZ=0,ux=0,uy=1,uz=0;
function la(a,b,t){var d=b-a;d-=6.2832*Math.round(d/6.2832);return a+d*t;}
function pt(x,y,z,c){x-=ex;y-=ey;z-=ez;var d=x*fx+y*fy+z*fz;if(d<.4)return;var l=15-((d*.28)|0);if(l<3)return;
 var px=(HW+(x*RX+z*RZ)*FOC/d)|0,py=(HH-(x*ux+y*uy+z*uz)*FOC/d)|0;if(px<1||px>=W-2||py<1||py>=H-2)return;
 var p=pal[c*16+l],o=py*W+px;buf[o]=p;if(d<11){buf[o+1]=p;buf[o+W]=p;if(d<5)buf[o+W+1]=p;}}
// ---- data ----
var CH=[{w:1,n:'OPERATOR',a:10,b:11,s:1,sp:1,dm:1,sk:'SPECIAL: LEAPING 360 ROUNDHOUSE'},{w:1.35,n:'EMBER BRUTE',a:0,b:1,s:1.18,sp:.9,dm:1.2,sk:'SPECIAL: FIREBALL'},{w:0.8,n:'FROST WRAITH',a:2,b:3,s:1.02,sp:1,dm:1,sk:'SPECIAL: ICE SHARD FAN'},{w:0.85,n:'VOLT STRIKER',a:4,b:5,s:.98,sp:1.25,dm:1,sk:'SPECIAL: LIGHTNING DASH'},{w:0.95,n:'VOID WEAVER',a:6,b:7,s:1,sp:1,dm:1.1,sk:'SPECIAL: GRAVITY PULL'},{w:1.6,n:'STONE GOLEM',a:8,b:9,s:1.35,sp:.75,dm:1.4,sk:'SPECIAL: QUAKE'}];
//      dur hitT reach dmg kb fwd jump
var MV=[0,[.26,.1,1.6,8,3,2,0],[.36,.14,2,12,4,0,0],[.42,.12,1.7,16,6,1,3],[.9,.4,2.5,26,8,4,6.5],[.42,.14,2.4,18,7,10,0],[.5,.18,2.1,16,6,4,5],[.4,.16,0,26,0,0,0],[.6,.35,5,22,9,0,0],[.9,.4,0,30,0,0,0],[1.3,.7,8,60,14,0,0],[.28,.05,0,0,0,9,0]];
var CO=[0,0,0,0,0,0,0,5,12,22,60,6];
var RAD=[.2,.13,.075,.065,.075,.065,.095,.08,.095,.08],NS=[320,90,56,56,56,56,90,90,90,90];
var ST=[{sc:2.2,hp:300,sp:2.4,rng:18,cd:2.6,dm:35,cc:12,bc:22},{sc:1.1,hp:120,sp:4,rng:11,cd:.7,dm:10,cc:13,bc:13},{sc:.55,hp:40,sp:6.5,rng:0,cd:.8,dm:5,cc:14,bc:14},{sc:1.5,hp:260,sp:4.5,rng:12,cd:1.6,dm:18,cc:23,bc:0},{sc:2,hp:420,sp:3,rng:0,cd:1.4,dm:30,cc:25,bc:25},{sc:.6,hp:50,sp:7,rng:0,cd:.7,dm:6,cc:24,bc:24}];
var CAMN=['TEKKEN CAM','CHASE CAM','CINEMA ORBIT','OVERHEAD','LOW HERO'];
function mk(ci,idx){return{ci:ci,idx:idx,x:0,y:0,z:0,vx:0,vz:0,vy:0,dx:0,dz:0,yaw:0,hp:1000,max:1000,en:100,mv:0,mt:0,hit:0,blk:0,bt:0,ph:0,stun:0,inv:0,ait:0,glow:0};}
var F=[mk(0,0),mk(1,1)],SG=[new Float32Array(60),new Float32Array(60)],LB=new Float32Array(24);
var SP=[],PJ=[],NFX=2400,FX=new Float32Array(NFX),FY=new Float32Array(NFX),FZ=new Float32Array(NFX),FVX=new Float32Array(NFX),FVY=new Float32Array(NFX),FVZ=new Float32Array(NFX),FL=new Float32Array(NFX),FC=new Uint8Array(NFX),fxp=0;
for(i=0;i<18;i++)SP.push({on:0,t:0,x:0,z:0,yaw:0,hp:0,sc:1,ph:0,cd:0,kx:0,kz:0,spd:0});
for(i=0;i<24;i++)PJ.push({on:0,x:0,y:0,z:0,vx:0,vy:0,vz:0,life:0,ow:0,dm:0,c:0,r:.5});
var CR=[{x:30,z:20,t:0},{x:-40,z:30,t:0},{x:10,z:-50,t:0},{x:-30,z:-35,t:0}];
// ---- state ----
var gs=0,mode=0,mi=0,cmode=0,wv=0,kills=0,wins=0,loss=0,msgT=0,msgS='',tgtOn=0,tgtX=0,tgtZ=0,tgtD=0,giants=0,alive=0;
var C={yaw:0,pitch:.2,dist:6,x:0,y:1,z:0,man:0};
function msg(s,t){msgS=s;msgT=t||2;}
function burst(x,y,z,n,s,c,life){n=(n*QF[Q])|0;for(var q=0;q<n;q++){var p=fxp;fxp=(fxp+1)%NFX;FX[p]=x;FY[p]=y;FZ[p]=z;FVX[p]=(Math.random()-.5)*s*2;FVY[p]=Math.random()*s;FVZ[p]=(Math.random()-.5)*s*2;FL[p]=life*(.5+Math.random()*.7);FC[p]=c;}}
// ---- pose ----
var gX,gY,gZ,gS,gC,gSn,gO,gT=0,gL=0;
function limb(o,sx,sy,sz,L1,L2,a,s,b){var ca=Math.cos(a),sa=Math.sin(a),cs=Math.cos(s),ss=Math.sin(s),a2=a+b;
 LB[o]=sx+ss*L1;LB[o+1]=sy-ca*cs*L1;LB[o+2]=sz+sa*cs*L1;LB[o+3]=LB[o]+ss*L2;LB[o+4]=LB[o+1]-Math.cos(a2)*cs*L2;LB[o+5]=LB[o+2]+Math.sin(a2)*cs*L2;}
function T3(o,s,lx,ly,lz){s[o]=gX+(lx*gC+lz*gSn)*gS;s[o+1]=gY+(ly+gO)*gS;if(s[o+1]<.04)s[o+1]=.04;s[o+2]=gZ+(-lx*gSn+lz*gC)*gS;}
function TW(o,s,lx,ly,lz){var c=Math.cos(gT),sn=Math.sin(gT),x=lx*c+lz*sn,z=-lx*sn+lz*c,dy=ly-.95,cl=Math.cos(gL),sl=Math.sin(gL);T3(o,s,x,.95+dy*cl-z*sl,z*cl+dy*sl);}
function pose(f,s){var m=f.mv,u=m?Math.min(1,f.mt/MV[m][0]):0,e=Math.sin(PI*u),v=Math.min(1,Math.sqrt(f.vx*f.vx+f.vz*f.vz)/5),ph=f.ph,sw=Math.sin(ph),c,x,mx,
 aR=.9-sw*.4*v,bR=1.9,aL=1.4+sw*.4*v,bL=1.2,sR=.35,sL=.2,tR=-.35+sw*.7*v,kR=.35+Math.max(0,-Math.sin(ph+1.3))*.9*v,tL=.35-sw*.7*v,kL=.3+Math.max(0,Math.sin(ph+1.3))*.9*v,ls=.16,lL=.16,yo=-.08-Math.abs(Math.cos(ph))*.03*v+Math.sin(fr*.08)*.03,tw=.35-sw*.25*v,ln=.08+.1*v,spin=0;
 if(f.blk){aR=aL=1.7;bR=bL=2;sR=sL=.1;kR=kL=.6;yo=-.15;tw=0;}
 if(m==1){aR=.9+.65*e;bR=1.9*(1-e);sR=.35-.3*e;tw=.35-1.1*e;aL=1.1;bL=1.4;ln=.15*e;tL=.55;kL=.4;tR=-.4;}
 else if(m==2){c=u<.4?u/.4:1;x=u<.4?0:(u-.4)/.6;tR=1.25*c+.3*x;kR=u<.4?1.7*c:1.7*(1-x);tL=0;kL=.35;ln=-.35*e;aR=-.3;bR=.6;aL=1.2;bL=.9;tw=.3;yo=-.04;}
 else if(m==3){aR=-.2+3*Math.min(1,u*1.6);bR=.3;tw=.6-.8*e;yo=-.1+.3*e;tL=.5;kL=.5;tR=-.4;kR=.4;ln=.1;}
 else if(m==4||(m==9&&f.ci==0)){spin=6.283*u;tR=1.5*e;kR=.3;ls=.1+.9*e;tL=0;kL=.4;yo=.05;aR=aL=1;sR=sL=1.3;bR=bL=.2;ln=-.2*e;tw=0;}
 else if(m==5){ln=.45;aR=1.55;bR=.1;sR=.05;aL=.5;bL=1.4;tL=.6;kL=.8;tR=-.9;kR=.3;yo=-.05;tw=.2;}
 else if(m==6){aR=aL=1.2;sR=sL=1.2;bR=bL=.3;tR=1.55*Math.min(1,u*3);kR=.1;tL=.5;kL=1.9;ln=-.4;tw=0;yo=0;}
 else if(m==7||m==9){aR=aL=1.55;bR=bL=.1;sR=sL=.15+(m==9?.6*e:0);tw=0;ln=.2*e;tL=.6;kL=.6;tR=-.6;kR=.4;yo=-.12;}
 else if(m==8){c=Math.max(0,(u-.5)*2);aR=aL=u<.5?1.1+3.6*u:2.9-3.2*c;bR=bL=.3;kR=kL=.2+1.2*c;tR=tL=.4*c;yo=-.35*c;ln=.3*c;tw=0;sR=sL=.2;}
 else if(m==10){aR=aL=1.5;bR=bL=.2;sR=sL=1.4*e+.2;tR=-.2;kR=1.8;tL=.9;kL=1.9;yo=.8*e;spin=3*u;tw=0;}
 else if(m==11){ln=-.3*e;aR=.8;tw=0;}
 var Y=f.yaw+spin;gX=f.x;gY=f.y;gZ=f.z;gS=CH[f.ci].s;gC=Math.cos(Y);gSn=Math.sin(Y);gO=yo-(kL>kR?kL:kR)*.04;gT=tw;gL=ln;
 limb(0,.2,1.42,0,.27,.25,aR,sR,bR);limb(6,-.2,1.42,0,.27,.25,aL,-sL,bL);limb(12,.1,.95,0,.47,.46,tR,ls,-kR);limb(18,-.1,.95,0,.47,.46,tL,-lL,-kL);
 T3(0,s,0,.95,0);TW(3,s,0,1.45,0);TW(6,s,0,1.6,0);TW(9,s,0,1.64,0);
 TW(12,s,.2,1.42,0);TW(15,s,LB[0],LB[1],LB[2]);TW(18,s,LB[0],LB[1],LB[2]);TW(21,s,LB[3],LB[4],LB[5]);
 TW(24,s,-.2,1.42,0);TW(27,s,LB[6],LB[7],LB[8]);TW(30,s,LB[6],LB[7],LB[8]);TW(33,s,LB[9],LB[10],LB[11]);
 T3(36,s,.1,.95,0);T3(39,s,LB[12],LB[13],LB[14]);T3(42,s,LB[12],LB[13],LB[14]);T3(45,s,LB[15],LB[16],LB[17]);
 T3(48,s,-.1,.95,0);T3(51,s,LB[18],LB[19],LB[20]);T3(54,s,LB[18],LB[19],LB[20]);T3(57,s,LB[21],LB[22],LB[23]);}
function extras(f,sg){var c=f.ci,C0=CH[c],S=C0.s,n=(30*QF[Q])|0,j,t,k,sn=Math.sin(f.yaw),cs=Math.cos(f.yaw),hx=sg[6],hy=sg[7],hz=sg[8],nx=sg[3],ny=sg[4],nz=sg[5];
 if(c==0){for(j=0;j<n;j++){t=j/n;k=Math.sin(fr*.2+t*6)*.08;pt(nx-sn*t*.9*S+cs*k,ny-t*.7*S,nz-cs*t*.9*S-sn*k,C0.a);}}
 else if(c==1){for(j=0;j<n;j++){t=j/n;k=(j&1)?1:-1;pt(hx+cs*k*(.12+t*.2)*S,hy+(.1+t*.45)*S,hz-sn*k*(.12+t*.2)*S,C0.b);pt(sg[12]+JT[j*3]*.15,sg[13]+((j*.13+fr*.06)%.7),sg[14]+JT[j*3+2]*.15,0);pt(sg[24]+JT[j*3]*.15,sg[25]+((j*.11+fr*.06)%.7),sg[26]+JT[j*3+2]*.15,1);}}
 else if(c==2){for(j=0;j<n*2;j++){t=(j*.037)%1;k=j*.7+fr*.08;pt(f.x+Math.cos(k)*(.25+t*.4)*S,.05+t*.9*S,f.z+Math.sin(k)*(.25+t*.4)*S,C0.b);}}
 else if(c==3){for(j=0;j<n;j++){k=(j%5)*1.2-2.4;t=((j/5)|0)/6;pt(hx+cs*Math.sin(k)*(.1+t*.25)*S,hy+Math.cos(k)*(.12+t*.3)*S,hz-sn*Math.sin(k)*(.1+t*.25)*S,5);}
  for(j=0;j<10;j++){t=Math.random();pt(sg[21]+(sg[33]-sg[21])*t+(Math.random()-.5)*.2,sg[22]+(sg[34]-sg[22])*t+(Math.random()-.5)*.2,sg[23]+(sg[35]-sg[23])*t+(Math.random()-.5)*.2,4);}}
 else if(c==4){for(j=0;j<n*2;j++){k=fr*.07+(j&3)*1.571;pt(f.x+Math.cos(k)*1.1*S+JT[j*3]*.12,1.1*S+Math.sin(k*2)*.2+JT[j*3+1]*.12,f.z+Math.sin(k)*1.1*S+JT[j*3+2]*.12,7);}
  for(j=0;j<n;j++)pt(hx+Math.cos(j*.5)*.25,hy+.35*S,hz+Math.sin(j*.5)*.25,6);}
 else{for(j=0;j<n*2;j++){pt(sg[12]+JT[j*3]*.3*S,sg[13]+.1*S+JT[j*3+1]*.25*S,sg[14]+JT[j*3+2]*.3*S,8);pt(sg[24]+JT[j*3]*.3*S,sg[25]+.1*S+JT[j*3+1]*.25*S,sg[26]+JT[j*3+2]*.3*S,8);}
  for(j=0;j<n;j++)pt(nx+JT[j*3]*.12,ny-.25+JT[j*3+1]*.12,nz+.15+JT[j*3+2]*.1,9);}}
function drawF(f,sg){var C0=CH[f.ci],S=C0.s,f4=fr>>2,qf=QF[Q],i,j;
 for(i=0;i<10;i++){var o=i*6,ax=sg[o],ay=sg[o+1],az=sg[o+2],dx=sg[o+3]-ax,dy=sg[o+4]-ay,dz=sg[o+5]-az,n=(NS[i]*qf)|0,r=RAD[i]*S*C0.w;
  for(j=0;j<n;j++){var t=TT[j],k=((j*7+i*53+f4)&511)*3;pt(ax+dx*t+JT[k]*r,ay+dy*t+JT[k+1]*r,az+dz*t+JT[k+2]*r,(j%3)?C0.a:C0.b);}}
 extras(f,sg);if(f.glow>0||f.en>=60){var n2=(36*qf)|0;for(j=0;j<n2;j++){var an=fr*.12+j*.7,rr=(.9+.2*Math.sin(j))*S;pt(f.x+Math.cos(an)*rr,.1+((j*.09+fr*.03)%2)*S,f.z+Math.sin(an)*rr,C0.b);}}}
// ---- combat ----
function shoot(f,dm,spd,r,ang){for(var i=0;i<24;i++){var p=PJ[i];if(!p.on){var Y=f.yaw+(ang||0),S=CH[f.ci].s;p.on=1;p.x=f.x+Math.sin(Y)*.8;p.y=1.2*S;p.z=f.z+Math.cos(Y)*.8;p.vx=Math.sin(Y)*spd;p.vz=Math.cos(Y)*spd;p.vy=0;p.life=2.2;p.ow=f.idx;p.dm=dm;p.c=CH[f.ci].a;p.r=r;return;}}}
function ko(w){if(mode==0){if(w){wins++;msg('K.O.! YOU WIN',3);}else{loss++;msg('K.O. — YOU LOSE',3);}resetArena();}else{msg('DOWNED · WAVE RESTARTS',3);F[0].hp=1000;F[0].max=1000;F[0].x=F[0].z=0;wv=Math.max(0,wv-1);for(var i=0;i<18;i++)SP[i].on=0;for(i=0;i<24;i++)PJ[i].on=0;wt=3;}}
function hurt(t,dm,sx,sz,kb){if(t.inv>0||t.hp<=0)return;var b=t.blk&&!t.mv;if(b){dm*=.15;kb*=.3;}t.hp-=dm;t.stun=b?.1:.28;var dx=t.x-sx,dz=t.z-sz,d=Math.sqrt(dx*dx+dz*dz)+.001;t.dx+=dx/d*kb*1.5;t.dz+=dz/d*kb*1.5;if(!b)t.mv=0;
 burst(t.x,1.1*CH[t.ci].s,t.z,b?10:30,5,CH[t.ci].b,.5);shk=Math.max(shk,b?.05:.15);if(t.hp<=0)ko(t.idx==1?1:0);}
function hurtSp(s,dm,sx,sz,kb,f){s.hp-=dm;var dx=s.x-sx,dz=s.z-sz,d=Math.sqrt(dx*dx+dz*dz)+.001;s.kx+=dx/d*kb*1.4/s.sc;s.kz+=dz/d*kb*1.4/s.sc;burst(s.x,s.sc*.8,s.z,24,5,CH[F[0].ci].a,.5);
 if(s.hp<=0){s.on=0;kills++;burst(s.x,s.sc*.8,s.z,70,7,ST[s.t].cc,.9);F[0].en=Math.min(100,F[0].en+15);shk=Math.max(shk,.12);}}
function hitAt(f,r,dm,kb,arc){var fx_=Math.sin(f.yaw),fz_=Math.cos(f.yaw),i,dx,dz,d;
 if(mode==0){var t=F[f.idx^1];dx=t.x-f.x;dz=t.z-f.z;d=Math.sqrt(dx*dx+dz*dz)+.001;if(d<r+.5&&(!arc||(dx*fx_+dz*fz_)/d>0))hurt(t,dm,f.x,f.z,kb);}
 else if(f.idx==0)for(i=0;i<18;i++){var s=SP[i];if(!s.on)continue;dx=s.x-f.x;dz=s.z-f.z;d=Math.sqrt(dx*dx+dz*dz)+.001;if(d<r+s.sc*.8&&(!arc||(dx*fx_+dz*fz_)/d>-.1))hurtSp(s,dm,f.x,f.z,kb);}}
function special(f){var c=f.ci,dm=30*CH[c].dm,fx_=Math.sin(f.yaw),fz_=Math.cos(f.yaw);f.glow=.8;
 if(c==0)hitAt(f,2.8,dm,9,0);
 else if(c==1)shoot(f,dm,11,1.1);
 else if(c==2){shoot(f,dm*.6,22,.5,-.3);shoot(f,dm*.6,22,.5,0);shoot(f,dm*.6,22,.5,.3);}
 else if(c==3){f.dx=fx_*28;f.dz=fz_*28;f.inv=.3;hitAt(f,4,dm,8,1);burst(f.x,1,f.z,80,8,4,.5);}
 else if(c==4){if(mode==0){var t=F[f.idx^1];t.dx+=(f.x-t.x)*5;t.dz+=(f.z-t.z)*5;}else for(var i=0;i<18;i++){var s=SP[i];if(s.on&&Math.abs(s.x-f.x)+Math.abs(s.z-f.z)<24){s.kx+=(f.x-s.x)*2.5;s.kz+=(f.z-s.z)*2.5;}}hitAt(f,6,dm*.6,0,0);burst(f.x,1,f.z,90,6,7,.7);}
 else{hitAt(f,7,dm*1.3,12,0);shk=.5;burst(f.x,.2,f.z,120,9,8,.8);}}
function doHit(f,m){var M=MV[m],dm=M[3]*CH[f.ci].dm;
 if(m==7)shoot(f,dm,18,.6);else if(m==9)special(f);
 else if(m==8||m==10){hitAt(f,M[2],dm,M[4],0);shk=m==10?.6:.3;f.glow=.6;burst(f.x,.2,f.z,m==10?160:90,m==10?10:7,CH[f.ci].a,.8);}
 else hitAt(f,M[2]*CH[f.ci].s,dm,M[4],1);}
function fstep(f,dt,mx,mz,req,tx,tz,face){var C0=CH[f.ci],M,sn,cs;
 if(f.stun>0){f.stun-=dt;mx=mz=0;req=0;}
 f.inv-=dt;f.en=Math.min(100,f.en+10*dt);if(f.glow>0)f.glow-=dt;
 if(req&&f.en>=CO[req]&&(!f.mv||f.mt>MV[f.mv][0]*.65||(req>f.mv&&f.mt<.2))){
  if(face)f.yaw=Math.atan2(tx-f.x,tz-f.z);M=MV[req];f.mv=req;f.mt=0;f.hit=0;f.en-=CO[req];sn=Math.sin(f.yaw);cs=Math.cos(f.yaw);
  f.dx=sn*M[5]*C0.sp;f.dz=cs*M[5]*C0.sp;if(req==11){f.dx=-f.dx;f.dz=-f.dz;f.inv=.3;}
  if(f.y<.05&&M[6])f.vy=M[6];if(req==9&&f.ci==0){f.vy=6.5;f.dx=sn*5;f.dz=cs*5;}}
