// ---- update ----
function update(dt,now){var P=F[0],E=F[1],i;input(now);
 if(gs==0){if((cur[2]&&!prv[2])||(AX[0]<-.6&&mAx>=-.6))mi=(mi+5)%6;if((cur[3]&&!prv[3])||(AX[0]>.6&&mAx<=.6))mi=(mi+1)%6;mAx=AX[0];
