 // target
 tgtOn=0;tgtD=1e9;if(mode==0){tgtOn=1;tgtX=E.x;tgtZ=E.z;tgtD=Math.sqrt((E.x-P.x)*(E.x-P.x)+(E.z-P.z)*(E.z-P.z));}
 else{giants=0;alive=0;for(i=0;i<18;i++){var s=SP[i];if(!s.on)continue;alive++;if(s.t==0)giants++;var d=Math.sqrt((s.x-P.x)*(s.x-P.x)+(s.z-P.z)*(s.z-P.z));if(d<tgtD&&d<30){tgtD=d;tgtX=s.x;tgtZ=s.z;tgtOn=1;}}}
 var cy=Math.cos(C.yaw),sy=Math.sin(C.yaw),mx=AX[0]*cy-AX[1]*sy,mz=-AX[0]*sy-AX[1]*cy,ml=Math.sqrt(mx*mx+mz*mz);if(ml>1){mx/=ml;mz/=ml;}
