 if(mode==0){aiThink(E,dt);var dx=E.x-P.x,dz=E.z-P.z,d=Math.sqrt(dx*dx+dz*dz);if(d<.9&&d>.001){P.x-=dx/d*.1;P.z-=dz/d*.1;E.x+=dx/d*.1;E.z+=dz/d*.1;}}
 else{wt-=alive?0:dt;if(!alive&&wt<=0){newWave();wt=4;}for(i=0;i<18;i++)if(SP[i].on)spUpd(SP[i],dt);
  for(i=0;i<4;i++){var c=CR[i];if(c.t>0){c.t-=dt;if(c.t<=0){var a=Math.random()*6.283,r=30+Math.random()*100;c.x=P.x+Math.cos(a)*r;c.z=P.z+Math.sin(a)*r;}continue;}
   if(Math.abs(c.x-P.x)+Math.abs(c.z-P.z)<3){P.max=Math.max(P.max,P.hp+500);P.hp+=500;c.t=18;burst(c.x,1.2,c.z,100,8,19,.9);msg('◆ HP CRYSTAL +500 ◆',1.5);}}}
 for(i=0;i<24;i++){var p=PJ[i];if(!p.on)continue;p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.z+=p.vz*dt;if(fr&1)burst(p.x,p.y,p.z,2,1,p.c,.35);
  if(p.life<=0||p.y<0){p.on=0;burst(p.x,Math.max(.1,p.y),p.z,16,4,p.c,.4);continue;}
  if(p.ow==0&&mode==1){var bn=null,bd=1e9,q;for(q=0;q<18;q++){var s2=SP[q];if(!s2.on)continue;var ad=Math.abs(s2.x-p.x)+Math.abs(s2.z-p.z);if(ad<p.r+s2.sc*1.3){hurtSp(s2,p.dm,p.x-p.vx,p.z-p.vz,5);p.on=0;break;}if(ad<bd){bd=ad;bn=s2;}}
  if(p.on&&bn){var ax=bn.x-p.x,az=bn.z-p.z,al=Math.sqrt(ax*ax+az*az)+.01,v0=Math.sqrt(p.vx*p.vx+p.vz*p.vz),kk=Math.min(1,dt*6);p.vx+=(ax/al*v0-p.vx)*kk;p.vz+=(az/al*v0-p.vz)*kk;p.vy+=((bn.sc*.8-p.y)/al*v0-p.vy)*kk;}}
  else{var t=p.ow==1||p.ow==2?P:E,dd=Math.abs(t.x-p.x)+Math.abs(t.z-p.z);if(p.ow==0&&mode==1)continue;if(dd<p.r+.8*CH[t.ci].s&&Math.abs(p.y-1.1)<1.6){hurt(t,p.dm,p.x-p.vx,p.z-p.vz,6);p.on=0;burst(p.x,p.y,p.z,25,5,p.c,.5);}}}
